import { readFileSync } from "node:fs";
import {
  deriveRoomPanel,
  type RoomObservationRound,
  type RoomPanelCheckReport,
  type RoomPanelFigure,
} from "../src/domain/costs/room-panel";
import type { EurostatSeries } from "../src/domain/costs/eurostat";
import type { StayData } from "../src/domain/costs/stay-figures";
import type { HoldoutResult } from "../src/domain/costs/holdout";

// SYNTHETIC. Room rounds come from tests/fixtures/room-observations (generated by
// scripts/room-panel-fixtures.mjs from the frozen panels); none is an observation.

export const ROUND_DATES = {
  vienna: "2026-11-17",
  milan: "2026-11-17",
  barcelona: "2026-11-17",
  london: "2026-11-10",
  istanbul: "2026-11-10",
} as const;
export type FixtureCity = keyof typeof ROUND_DATES;

export function fixtureRound(city: FixtureCity) {
  const base = `tests/fixtures/room-observations/${city}/${ROUND_DATES[city]}`;
  return {
    round: JSON.parse(
      readFileSync(`${base}.json`, "utf8"),
    ) as RoomObservationRound,
    report: JSON.parse(
      readFileSync(`${base}.check.json`, "utf8"),
    ) as RoomPanelCheckReport,
  };
}
export const REVIEW_AFTER = "2027-02-15";
export function reviewedFigure(city: FixtureCity): RoomPanelFigure {
  const { round, report } = fixtureRound(city);
  const result = deriveRoomPanel(round, report, { reviewAfter: REVIEW_AFTER });
  if (!result.ok) throw Error(result.errors.join(" "));
  return {
    ...result.figure,
    review: {
      status: "reviewed",
      reviewer: "synthetic-test",
      reviewedAt: "2026-11-18",
    },
  };
}

